  }]]},{move_to={ -4.159154, 0.099868, -5.017212 }, json=[[{"GUID": "6a1fe4", "Name": "Custom_Tile", "Transform": {"posX": -74.7787, "posY": 1.69474232, "posZ": 30.953907, "rotX": 0.0182202309, "rotY": 179.956573, "rotZ": 0.00720545463, "scaleX": 8.82, "scaleY": 1.0, "scaleZ": 8.82}, "Nickname": "Lizard Board", "Description": "", "GMNotes": "", "ColorDiffuse": {"r": 0.905, "g": 0.898, "b": 0.1719957}, "LayoutGroupSortIndex": 0, "Value": 0, "Locked": true, "Grid": true, "Snap": true, "IgnoreFoW": false, "MeasureMovement": false, "DragSelectable": true, "Autoraise": true, "Sticky": true, "Tooltip": false, "GridProjection": false, "HideWhenFaceDown": false, "Hands": false, "CustomImage": {"ImageURL": "https://cdn.jsdelivr.net/gh/mrdrouf/root-tabletop-tournament@main/assets/labels/lizard_board_v2_167c61ed.png", "ImageSecondaryURL": "https://steamusercontent-a.akamaihd.net/ugc/1807607729518169828/BF093EA9F278FAF85874FF396741D029A117A270/", "ImageScalar": 1.0, "WidthScale": 0.0, "CustomTile": {"Type": 0, "Thickness": 0.1, "Stackable": false, "Stretch": true}}, "LuaScript": "----#include root\\lizardboard\n-- THE BOARD READS THE WIZARD. The Lizard Wizard is the public tracker -- the Outcast Marker sits in\n-- one of its three slots and the discarded cards pile on it -- and this board's own Outcast panel and\n-- Lost Souls box are printed copies of the same two things. Maintainer, 2026-09-07: \"could you have\n-- the outcast on the faction board follow the information on the lizard wizard? so have the symbol\n-- for the outcast suit and then when it s heated and the counter for the number of cards of each suit\n-- in the lost souls.\"\n--\n-- It used to cast a physics box at THIS board's own Lost Souls area, which is empty in every game the\n-- mod sets up, because the cards go on the wizard. So the three numbers read 0 0 0 for ever.\n--\n-- The wizard is the only source, by the maintainer's choice: \"The Wizard, always\". A card dropped on\n-- this board's own printed box is not counted, and with no wizard on the table the readout is blank\n-- rather than wrong.\n\n-- Every card carries its suit in its DESCRIPTION -- \"Fox\", \"Bird\", \"Rabbit\", \"Mouse\" -- which is how\n-- the dominance cards are read too. Birds are deliberately not counted: the Outcast is the most common\n-- suit of Lost Souls IGNORING birds, so a bird count would be a number nobody can use.\nSUITS = { \"mouse\", \"rabbit\", \"fox\" }\n\n-- The three Outcast slots, in the WIZARD's own local frame, from its blueprint's snap points. Its\n-- fourth snap, out at x 0.48, is where the Lost Souls pile goes.\nSLOT_X  = -0.73\nSLOT_Z  = { mouse = 0.0284, rabbit = 0.3749, fox = 0.7320 }\nPILE_X  = { 0.05, 0.95 }        -- the Lost Souls half of the wizard, in its local x\nPILE_Z  = 0.9                   -- ...and how far either side of its middle\n\n-- THIS BOARD'S OWN THREE OUTCAST SLOTS -- the printed thorn boxes under the mouse, rabbit and fox\n-- icons, left to right on the art. MEASURED OFF THE BOARD TEXTURE rather than off the snap points:\n-- each frame's ink box was flood-filled on the 1689px art, putting the three centres at px 1305.5,\n-- 1431.0 and 1563.5, all at py 619, and the art maps to local space at 657.4 px per unit about\n-- px (842.2, 655.2). Snap 6 sits 2.8px left of its own printed frame -- only 0.004 local, but the\n-- symbol is drawn INSIDE a 92px frame and there is no reason to spend a twentieth of that gap.\n--\n-- Local -x is image RIGHT and local +z is image DOWN, confirmed by laying the Gardens grid's snap\n-- points over the printed grid: all 15 land on their cells to about a pixel.\nBOARD_SLOT = { mouse = -0.7047, rabbit = -0.8956, fox = -1.0972 }\nBOARD_SLOT_Z = -0.0551\n\nmice = 0\nbunnies = 0\nfoxes = 0\noutcast = nil                   -- \"mouse\" / \"rabbit\" / \"fox\", or nil when the marker is not in a slot\nhated = false\nwait_id = 0\n\nfunction onLoad(save_state)\n  createButtons()\n  wait_id = Wait.time(updateButtons, 1, -1)\nend\n\nfunction onDestroy()\n  Wait.stop(wait_id)\nend\n\nfunction nothing()\nend\n\nfunction addCard(suit)\n  suit = tostring(suit or \"\"):lower()\n  if string.find(suit, \"fox\", 1, true) then foxes = foxes + 1 end\n  if string.find(suit, \"mouse\", 1, true) then mice = mice + 1 end\n  if string.find(suit, \"rabbit\", 1, true) then bunnies = bunnies + 1 end\nend\n\nfunction findByName(want)\n  for _, o in ipairs(getAllObjects()) do\n    if (o.getName() or \"\") == want then return o end\n  end\n  return nil\nend\n\n-- WHICH SLOT THE MARKER IS IN, in the wizard's frame rather than the world's -- so the answer does not\n-- change when the wizard is moved or turned.\nfunction readOutcast(wiz)\n  local m = findByName(\"Outcast Marker\")\n  if wiz == nil or m == nil then return nil, false end\n  local ok, l = pcall(function() return wiz.positionToLocal(m.getPosition()) end)\n  if not ok or l == nil then return nil, false end\n  if math.abs(l.x - SLOT_X) > 0.35 then return nil, false end   -- not on the slot column at all\n  local best, bestd = nil, 0.22\n  for _, suit in ipairs(SUITS) do\n    local d = math.abs(l.z - SLOT_Z[suit])\n    if d < bestd then best, bestd = suit, d end\n  end\n  -- the marker's other face is the Hated Outcast\n  return best, (m.is_face_down == true)\nend\n\n-- WHAT IS ON THE WIZARD'S LOST SOULS HALF. Counted by POSITION rather than by a physics cast: a cast\n-- has to be given a size in world units and the wizard is nearly four times scale, which is exactly\n-- the sort of number that is right until someone rescales the board.\nfunction countLostSouls(wiz)\n  if wiz == nil then return end\n  for _, o in ipairs(getAllObjects()) do\n    local t = o.tag or o.name\n    if t == \"Card\" or t == \"Deck\" then\n      local ok, l = pcall(function() return wiz.positionToLocal(o.getPosition()) end)\n      if ok and l ~= nil and l.x > PILE_X[1] and l.x < PILE_X[2] and math.abs(l.z) < PILE_Z then\n        if t == \"Card\" then\n          addCard(o.getDescription())\n        else\n          for _, c in ipairs(o.getObjects() or {}) do addCard(c.description) end\n        end\n      end\n    end\n  end\nend\n\n-- A BUTTON'S X IS MIRRORED AGAINST THE MODEL'S, BUT ITS Z IS NOT. This board's snap points put the\n-- Outcast panel at NEGATIVE local x and the buttons that sit on that same panel at POSITIVE, so the\n-- x fed to createButton is the NEGATION of the slot's -- which is why they are derived from\n-- BOARD_SLOT rather than written out, so the numbers and the symbol cannot drift apart.\n--\n-- The z is NOT negated, and that is not symmetry, it is measurement: -0.17 was fed in expecting it\n-- to land below the slots and it landed at local z -0.17, which is the middle of the suit icon row\n-- (-0.2171..-0.1380) -- the numbers printed over the mouse, rabbit and fox. A reflection in x, not\n-- a turn.\n--\n-- THERE IS SOMEWHERE TO PUT THEM NOW. The printed slots end at local z +0.0134 and the Outcast\n-- panel used to end at +0.0408 -- eighteen rows of parchment, no room for a numeral anywhere on\n-- it. Maintainer, 2026-09-08: \"increase the size of the parchment box with the decals so you\n-- create space to put the numbers below the boxes with the outcase.\" tools/make_board.py lifts the\n-- panel's torn bottom edge -- flourish, notch and ink -- and sets it down 80 rows lower, so the\n-- floor is at local z +0.163 and the counts sit in the clear band between.\nCOUNT_Z = 0.0834              -- local z; texture row 710, midway between the slots and the new floor\n\nfunction createButtons()\n  for _, suit in ipairs(SUITS) do\n    self.createButton({ click_function = \"nothing\", function_owner = self, label = \"0\",\n      position = { -BOARD_SLOT[suit], 0.1, COUNT_Z }, scale = { 0.5, 0.5, 0.5 },\n      width = 0, height = 0, font_size = 120 })\n  end\nend\n\n-- THE SYMBOL IS DRAWN ON THE BOARD, as part of its own face. Maintainer, 2026-09-07: \"can you make\n-- the symbol be inside the faction board, not another token on token. like it s literally the faction\n-- board art.\"\n--\n-- NOT A DECAL. That was tried four times and failed in one consistent voice: sunk onto the face it\n-- painted nothing, and it only ever appeared once the projector was lifted clear of the board --\n-- \"the current decal is above the lizard board !! not exactly on it\", then \"I don t see anymore the\n-- decals\" the moment it was lowered again. A decal attached to an object does not paint that object;\n-- lifting it merely shows the projector hanging in the air.\n--\n-- Object XmlUI does paint the object, and this mod already leans on it: the box score and the turn\n-- panel are both drawn that way. An Image in the board's own UI is part of the board's face, cannot\n-- be picked up, and needs no cleaning up.\n--\n-- THE PICTURES are the Outcast token's own two faces with their flat yellow tile taken off -- the\n-- front is the grey Outcast, the back the RED Hated Outcast with a crossed circle, so hated is a\n-- different picture rather than a tint. tools/make_outcast.py cuts them: the yellow comes off by\n-- unmixing each pixel along the yellow-to-ink line, which leaves real alpha instead of a keyed\n-- fringe, and the crop is SQUARE AND CENTRED ON THE DRAWING with the tile's stray specks dropped.\n-- That is what lets UI_SIZE below be the symbol's width directly, with no margin to divide out,\n-- and it is why both faces can share one size despite being drawn slightly differently.\nOUTCAST_IMG = \"https://cdn.jsdelivr.net/gh/mrdrouf/root-tabletop-tournament@main/assets/labels/outcast_v7_085c27c8.png\"\nHATED_IMG   = \"https://cdn.jsdelivr.net/gh/mrdrouf/root-tabletop-tournament@main/assets/labels/outcast_hated_v7_d9c16b63.png\"\n-- ...and the EMPTY slot, which the board no longer has printed on it. Its white thorn square used\n-- to be part of the texture and the symbol was drawn over it, which cannot be made to line up:\n-- the texture is placed by a fitted map and the symbol by the UI, and the two agree to about a\n-- pixel -- and a hard-edged stamp cannot hide under a drawing whose whole rim is part-transparent\n-- anyway. Maintainer, 2026-09-09: \"it does not perfectly covers the white still some white\n-- appear but you should be able to control perfectly both not sure why.\" Quite so, and the way\n-- to control both is to draw both the same way. Every slot is a UI image now, at one position and\n-- one size, so the white is REPLACED by the symbol rather than hidden under it.\nSLOT_IMG    = \"https://cdn.jsdelivr.net/gh/mrdrouf/root-tabletop-tournament@main/assets/labels/slot_v7_180af900.png\"\n\n-- THE MAPPING. An object's UI is measured in pixels at PX_PER_UNIT to one unit of the object's local\n-- space -- 100, the density the box score measured on a live table -- so a slot at local x -0.7047\n-- is at -70.47 px.\n--\n-- THE CANVAS IS TURNED 180 DEGREES AGAINST THE ART, and that is one fact with two halves. The first\n-- version landed on the correct SIDE of the board with UI x = +local x -- and local +x is image LEFT\n-- -- yet well BELOW its slot, hanging off the bottom of the Outcast panel into the Lost Souls title.\n-- A canvas cannot be mirrored, only turned; so if UI x+ is image left then UI y+ is image DOWN, which\n-- is local +z. UI y therefore runs WITH local z and the negation that was here was wrong. (The Image\n-- carries rotation 0 0 180 for the same reason -- it spins the art upright again on a turned canvas.)\n--\n-- UI_MIRROR is the one number to change if the symbol lands on the wrong side of the board, UI_Z_SIGN\n-- if it lands above its slot rather than in it. Buttons on this board are mirrored in x but NOT in z\n-- -- a reflection, not a turn -- so the two systems really do disagree, and each is pinned by its own\n-- observation rather than by one rule stretched over both.\nPX_PER_UNIT = 100\nUI_MIRROR   = 1               -- set to -1 if the symbol appears on the opposite side of the board\nUI_Z_SIGN   = 1               -- set to -1 if the symbol appears above its slot instead of inside it\nUI_SIZE     = 13.88           -- px; 0.1388 local. THE BOARD'S SLOT IS NOW THIS DRAWING. It used\n                              -- to be the printed thorn frame, which is the same square in a\n                              -- heavier hand, so the symbol laid over it left white showing all\n                              -- round -- and that was being beaten by fattening the symbol's ink,\n                              -- which is treating the symptom. Maintainer, 2026-09-09: \"instead of\n                              -- trying to fill the white space with the decal you could redo the\n                              -- white shape on the board so you fill it perfectly and so erase the\n                              -- white drawing by painting with the background color ... it also\n                              -- allows you to make the decal not so fat as it is now and its normal\n                              -- thinness.\"\n                              --\n                              -- So tools/make_board.py paints the printed frames out and stamps this\n                              -- same ring back in white, at this same size and centre. The symbol\n                              -- covers its own outline exactly and is drawn at its own weight, with\n                              -- no dilation at all.\n                              --\n                              -- THIS NUMBER AND THE TOOL'S RING_LOCAL ARE THE SAME MEASUREMENT. Change\n                              -- one and the white stops being covered; change both and it still is.\n                              -- If a hairline of white shows on ONE side, that is placement, not size:\n                              -- erode the stamp a pixel in make_board.py. If it shows all round, the\n                              -- sizes have drifted apart.\n\nSHOWN = nil                   -- what is drawn now, so the XML is only rewritten on a change\nUI_ASSETS_DONE = false\nUI_WARNED = false\n\nfunction uiAssetsOnce()\n  if UI_ASSETS_DONE then return end\n  UI_ASSETS_DONE = true\n  pcall(function()\n    self.UI.setCustomAssets({\n      { name = \"outcastImg\", url = OUTCAST_IMG },\n      { name = \"hatedImg\",   url = HATED_IMG },\n      { name = \"slotImg\",    url = SLOT_IMG },\n    })\n  end)\nend\n\n-- EVERY SLOT IS DRAWN, all three, every time: the two that are not the Outcast get the white thorn\n-- square the board used to have printed on it, and the one that is gets the symbol in its place.\n-- Same art size, same centres, same UI -- so there is no covering up to get right.\nfunction showOutcast()\n  local want = \"none\"\n  if outcast ~= nil then want = outcast .. (hated and \"-hated\" or \"\") end\n  if want == SHOWN then return end\n  SHOWN = want\n  uiAssetsOnce()\n  local parts = {}\n  for _, suit in ipairs(SUITS) do\n    local img = \"slotImg\"\n    if suit == outcast then img = hated and \"hatedImg\" or \"outcastImg\" end\n    parts[#parts + 1] = string.format(\n      '<Image id=\\\"slot%s\\\" image=\\\"%s\\\" width=\\\"%.2f\\\" height=\\\"%.2f\\\"'\n      .. ' position=\\\"%.1f %.1f -12\\\" rotation=\\\"0 0 180\\\" raycastTarget=\\\"false\\\"/>',\n      suit, img, UI_SIZE, UI_SIZE,\n      UI_MIRROR * BOARD_SLOT[suit] * PX_PER_UNIT, UI_Z_SIGN * BOARD_SLOT_Z * PX_PER_UNIT)\n  end\n  local ok, err = pcall(function() self.UI.setXml(table.concat(parts)) end)\n  if not ok and not UI_WARNED then\n    UI_WARNED = true\n    pcall(function()\n      broadcastToAll(\"Lizard board: the outcast slots could not be drawn (\" .. tostring(err) .. \")\",\n                     { r = 1, g = 0.6, b = 0.2 })\n    end)\n  end\nend\n\nfunction updateButtons()\n  mice, bunnies, foxes = 0, 0, 0\n  outcast, hated = nil, false\n  local wiz = findByName(\"Lizard Wizard\")\n  countLostSouls(wiz)\n  outcast, hated = readOutcast(wiz)\n\n  self.editButton({ index = 0, label = tostring(mice) })\n  self.editButton({ index = 1, label = tostring(bunnies) })\n  self.editButton({ index = 2, label = tostring(foxes) })\n  showOutcast()\nend\n\n----#include root\\lizardboard", "LuaScriptState": "", "XmlUI": "", "AttachedSnapPoints": [{"Position": {"x": -0.6259084, "y": 0.100000218, "z": -0.632033467}, "Rotation": {"x": 5.99166124e-05, "y": 0.0142067941, "z": 4.573914e-05}}, {"Position": {"x": -0.769556463, "y": 0.100000188, "z": -0.627778}, "Rotation": {"x": 5.99166124e-05, "y": 0.0142067941, "z": 4.573914e-05}}, {"Position": {"x": -0.9287303, "y": 0.100000158, "z": -0.6352461}, "Rotation": {"x": 5.99166124e-05, "y": 0.0142067941, "z": 4.573914e-05}}, {"Position": {"x": -1.08971775, "y": 0.100000158, "z": -0.628967345}, "Rotation": {"x": 5.99166124e-05, "y": 0.0142067941, "z": 4.573914e-05}}, {"Position": {"x": -0.705245, "y": 0.100001052, "z": -0.0574975833}, "Rotation": {"x": -1.8441159e-06, "y": 359.989746, "z": 1.00292164e-06}}, {"Position": {"x": -0.891449749, "y": 0.09999992, "z": -0.0575344637}, "Rotation": {"x": 7.046069e-07, "y": 359.989777, "z": -2.59421336e-06}}, {"Position": {"x": -1.09670246, "y": 0.100001104, "z": -0.0575742759}, "Rotation": {"x": 6.749056e-08, "y": 359.989777, "z": 1.34829136e-07}}, {"Position": {"x": 0.2950477, "y": 0.09999977, "z": 0.8077995}, "Rotation": {"x": 1.1867844e-06, "y": 0.00469916966, "z": 1.89807992e-07}}, {"Position": {"x": 0.292307973, "y": 0.0999990553, "z": 0.625745952}, "Rotation": {"x": 5.898826e-07, "y": 0.005327547, "z": 1.60074876e-06}}, {"Position": {"x": 0.294280678, "y": 0.0999993, "z": 0.444107056}, "Rotation": {"x": 9.760769e-07, "y": 359.99295, "z": 7.5864655e-08}}, {"Position": {"x": 0.09744962, "y": 0.100001037, "z": 0.624887645}, "Rotation": {"x": 3.18591037e-06, "y": 0.00531388726, "z": -1.12621433e-06}}, {"Position": {"x": 0.0983459353, "y": 0.100001976, "z": 0.8101389}, "Rotation": {"x": 3.07677078e-06, "y": 0.00469917, "z": -1.1084403e-06}}, {"Position": {"x": -0.08544233, "y": 0.100004584, "z": 0.6222505}, "Rotation": {"x": -9.46672e-08,