  }]]},{move_to={ -3.046032, 0.099997, 6.025470 }, json=[[{"GUID": "dda98a", "Name": "Custom_Tile", "Transform": {"posX": -5.03244448, "posY": 35.85192, "posZ": -45.068222, "rotX": 0.0164186079, "rotY": 179.963364, "rotZ": 0.08012102, "scaleX": 0.75087, "scaleY": 1.0, "scaleZ": 0.75087}, "Nickname": "Enclave", "Description": "", "GMNotes": "", "AltLookAngle": {"x": 0.0, "y": 0.0, "z": 0.0}, "ColorDiffuse": {"r": 0.6901961, "g": 0.5960784, "b": 0.0156862736}, "Tags": ["Frog Token"], "LayoutGroupSortIndex": 0, "Value": 0, "Locked": false, "Grid": false, "Snap": false, "IgnoreFoW": false, "MeasureMovement": false, "DragSelectable": true, "Autoraise": true, "Sticky": true, "Tooltip": true, "GridProjection": false, "HideWhenFaceDown": false, "Hands": false, "CustomImage": {"ImageURL": "https://dl.dropboxusercontent.com/scl/fi/z6by4u1a9m58vs2jrk68j/Diaspora_TokenPeaceful.png?rlkey=r74d1yel8gtebve0rhnitjrky&dl=0", "ImageSecondaryURL": "https://dl.dropboxusercontent.com/scl/fi/3jx2cllc775xaork61mow/EnclaveTokens-06.png?rlkey=q2d5x0d50jqfgqyvosqp2izcq&dl=0", "ImageScalar": 1.0, "WidthScale": 0.0, "CustomTile": {"Type": 2, "Thickness": 0.1, "Stackable": false, "Stretch": true}}, "LuaScript": "-- An enclave belongs on the suit marker's circle, facing the middle of the clearing. It used to land\n-- on the MAP's snap lattice instead (139 warrior/building slots ~1.49 apart, the only snap points\n-- near a clearing), which is why it sat beside the circle. Snapping is off for this token (Grid/Snap\n-- false in the blueprint); this places and turns it.\n--\n-- WHERE. The circle is the marker's suit lobe, and it is NOT the marker's origin. Measured off the\n-- marker mesh: its texture was hole-filled so the white suit glyph could not cap the search, the\n-- largest circle inscribed in the lobe found, and its centre mapped back through the mesh UVs ->\n-- model-local (0.0056, 0.0174, 0.3599). The glyph itself sits off the lobe centre (z 0.4447), so\n-- aiming at the symbol missed by 0.11 world units.\n--\n-- WHICH WAY. The marker's OWN rotation already points at its clearing centre -- checked over all 68\n-- well-matched suit markers on the six maps: the offset between a marker's rotY and the bearing from\n-- its lobe to its clearing centre is +0.03 deg, concentration 0.9944. So the enclave simply copies\n-- the marker's rotation, which is exact per clearing. (An earlier version computed the bearing from\n-- RTT_CLEARING_CENTRES instead and looked tilted: that table is calibrated to about a world unit, and\n-- the 6.1 deg residual in the check above is ITS error, not the markers'.)\n-- If the frog reads outward rather than inward, FROG_FACING = 180 is the whole fix.\nlocal LOBE_LOCAL  = { x = 0.0056, y = 0.0174, z = 0.3599 }\n-- WHERE THE PEACEFUL SIDE GOES: model-local, added to the lobe centre, in the MARKER's own frame.\n--\n-- NOT GUESSED -- MEASURED. The maintainer put a sympathy token on a fox marker to show the spot:\n-- \"check the save 'snap' I put 1 sympathy token on the map on 1 fox suit marker to show you the\n-- position I want for the side snap.\" That save is kept at assets/src_art/saves/snap.json and the\n-- test reads these two numbers back out of it, so they cannot drift from what he laid out.\n--\n-- It is not the pure sideways shift I had been using: the spot is 1.28 local from the lobe, mostly\n-- across the marker but with a real component back along its axis (+z points at the clearing centre,\n-- so -z is away from it). Two guesses at this -- 0.769 then 1.00, both on x alone -- are what the\n-- measurement replaces.\nlocal SIDE_LOCAL  = { x = -1.1906, z = -0.4791 }\n-- ...AND SITS AT AN ANGLE THERE. In-plane, on top of the marker's own facing, and only in this\n-- position: the centre spot is square with the lobe and wants no tilt. NEGATIVE IS COUNTERCLOCKWISE\n-- seen from above -- TTS turns clockwise on a rising Y -- so the maintainer's \"the side snap rotate\n-- the enclave counterclockwise by 20 degrees\" (2026-09-07) is -20, measured from the marker's own\n-- facing rather than from the +10 it had before.\nlocal SIDE_TILT   = -20\n-- HOW CLOSE YOU HAVE TO DROP IT. 4.0 caught an enclave aimed at nothing in particular and pulled it\n-- onto a marker from most of a clearing away -- \"the snaps are too large like it attaches the enclave\n-- from such a large area a bit too much\". 2.2 is a little over the lobe's own diameter, so the token\n-- has to be dropped on the marker to be taken by it. 4.0 -> 2.2 -> 3.0 -> 2.55, the last of those\n-- being \"decrease the area of the snap grab by 15%\" (2026-09-07) applied to his own 3.0.\n--\n-- THERE IS A FLOOR UNDER THIS. A token at the side spot sits 1.67 world units from the lobe, and it\n-- has to find its own marker from there when it is flipped back -- so REACH can come down to about\n-- 1.7 and no further. At 2.55 there is half a unit of room left.\nlocal REACH       = 2.55\nlocal FROG_FACING = 0     -- degrees added to the marker's own rotation\nlocal MILITANT_FACE_DOWN = true\n-- HOW FAR THE TOKEN RIDES ABOVE THE BOARD WHILE IT CROSSES. The glide used to run at whatever height\n-- the token was resting at, which is ON the marker -- so on its way between the two spots it ploughed\n-- through the marker's own relief and the map under it. Maintainer, 2026-09-07: \"during the flip it\n-- goes a bit under the marker and conflicts with the map.\"\n--\n-- IT IS NEVER PUT BACK DOWN BY HAND. The first version returned it to the height it lifted from, and\n-- that is wrong for the same reason the lift is needed: the two spots are at DIFFERENT heights. The\n-- lobe is raised, so a token carrying its side-spot height to the centre lands inside the marker --\n-- \"on militant it lands too low on some markers\". It is released at the crossing height and falls,\n-- which is what finds the right surface at either end. LIFT_FROM only anchors the crossing, so a\n-- token cannot climb by being flipped over and over.\nlocal GLIDE_LIFT  = 0.5\nLIFT_FROM = nil           -- the height the crossing is measured from, cleared once it lands\nlocal FLIP_SETTLE = 0.25  -- seconds between checks while a flip is still in the air\nlocal SETTLE_TRIES = 24   -- ~6s, then give up rather than hang on a token that never lands\n\n-- The marker this token was last placed on. Preferred over a fresh search so a token sitting out at\n-- the side spot cannot be claimed by a neighbouring clearing when it is flipped.\nHOME_GUID = nil\n\nfunction onSave() return JSON.encode({ h = HOME_GUID }) end\n\nfunction onLoad(state)\n  pcall(function()\n    if state ~= nil and state ~= \"\" then\n      local d = JSON.decode(state)\n      if type(d) == \"table\" then HOME_GUID = d.h end\n    end\n  end)\nend\n\nlocal function markerNear(p)\n  -- the one we are already on, if it is still in reach...\n  if HOME_GUID ~= nil then\n    local m = getObjectFromGUID(HOME_GUID)\n    if m ~= nil then\n      local ok, lobe = pcall(function() return m.positionToWorld(LOBE_LOCAL) end)\n      if ok and lobe ~= nil then\n        local dx, dz = lobe.x - p.x, lobe.z - p.z\n        if dx * dx + dz * dz <= REACH * REACH then return m end\n      end\n    end\n  end\n  -- ...otherwise the nearest lobe. Distance is ALWAYS measured to the lobe, never to the side spot,\n  -- so which clearing a token belongs to never depends on which way up it is.\n  local best, bestd = nil, REACH * REACH\n  for _, m in ipairs(getObjectsWithTag(\"Clearing Marker\")) do\n    local ok, lobe = pcall(function() return m.positionToWorld(LOBE_LOCAL) end)\n    if ok and lobe ~= nil then\n      local dx, dz = lobe.x - p.x, lobe.z - p.z\n      local d = dx * dx + dz * dz\n      if d < bestd then best, bestd = m, d end\n    end\n  end\n  return best\nend\n\n-- MILITANT ON THE SYMBOL, PEACEFUL BESIDE IT. Maintainer, 2026-09-07: \"when it s militant in the\n-- center of the suit marker, but when not militant the snap should be on the side of the suit marker\n-- at the edge of it so it does not hide the suit symbol.\"\n--\n-- WHICH WAY UP IS MILITANT. The blueprint's ImageURL is \"Diaspora_TokenPeaceful\" and all twelve spawn\n-- at rotZ 0, so a fresh token shows the peaceful face and is_face_down is true exactly when the\n-- militant side is up. This was briefly inverted, on a misreading of \"the center snap still flips it\n-- to peaceful while it should be militant\" -- the token really was being FLIPPED there, by the\n-- setRotation below, and the face test was never the problem. One constant either way.\n-- Where a token of this face belongs on this marker, in world space.\nlocal function spotOn(m, militant)\n  local target = { x = LOBE_LOCAL.x, y = LOBE_LOCAL.y, z = LOBE_LOCAL.z }\n  if not militant then\n    target.x = target.x + SIDE_LOCAL.x\n    target.z = target.z + SIDE_LOCAL.z\n  end\n  local ok, w = pcall(function() return m.positionToWorld(target) end)\n  if ok then return w end\n  return nil\nend\n\n-- MOVE WHILE IT TURNS. Maintainer, 2026-09-07: \"is it possible that the enclave move from 1 snap to\n-- the other during the flip not after landing?\" -- so the token glides across as it flips, instead of\n-- turning in place and then jumping.\n--\n-- onRotate fires as the turn STARTS, so is_face_down still reads the OLD face. The new one is simply\n-- its opposite, because a flip is a flip -- which is more dependable than reading the angle argument,\n-- whose units this does not need to know.\nfunction rttGlideToSpot()\n  if self.held_by_color ~= nil then return end\n  local m = markerNear(self.getPosition())\n  if m == nil then return end\n  local militant = ((self.is_face_down ~= true) == MILITANT_FACE_DOWN)\n  local w = spotOn(m, militant)\n  if w == nil then return end\n  pcall(function() HOME_GUID = m.getGUID() end)\n  local p = self.getPosition()\n  if LIFT_FROM == nil then LIFT_FROM = p.y end     -- a second flip mid-glide keeps the FIRST height\n  -- `fast` is TTS's only speed control for a scripted move -- there is no duration -- and the\n  -- maintainer wants the flip quicker: \"makes the flip animation 30% faster\" (2026-09-07). Both the\n  -- glide and the turn take it, so the two stay in step.\n  pcall(function() self.setPositionSmooth({ w.x, LIFT_FROM + GLIDE_LIFT, w.z }, false, true) end)\n  -- ...AND TURN AS IT GOES. Maintainer, 2026-09-07: \"the rotation though happens only after it lands\n  -- not during the flip.\"\n  --\n  -- THE TARGET INCLUDES THE FLIP, and that is the whole trick. Any rotation call issued now is racing\n  -- TTS's own flip animation, so the safe move is to name the orientation the token should END in --\n  -- turned AND flipped -- and let either of us get it there. Whichever lands last, the answer is the\n  -- same.\n  --\n  -- rotate() was tried here and broke the flip outright: it is RELATIVE, so it replaced TTS's\n  -- in-flight animation with one that only moved Y, and the token stopped flipping at all\n  -- (maintainer, 2026-09-07: \"it does not flip anymore when we flip it you broke something\").\n  --\n  -- Z IS THE FLIP AXIS -- established the hard way, when a placement that zeroed it turned every\n  -- landing face-up. onRotate fires before the turn, so the current Z is the pre-flip value and the\n  -- destination is that plus half a turn.\n  local okr, r = pcall(function() return m.getRotation() end)\n  local okc, c = pcall(function() return self.getRotation() end)\n  if okr and r ~= nil and okc and c ~= nil then\n    local wantY = (r.y + FROG_FACING + (militant and 0 or SIDE_TILT)) % 360\n    pcall(function() self.setRotationSmooth({ c.x, wantY, (c.z + 180) % 360 }, false, true) end)\n  end\nend\n\nfunction rttPlaceOnMarker()\n  if self.held_by_color ~= nil then return end        -- someone is holding it; onDrop will do this\n  local p = self.getPosition()\n  local m = markerNear(p)\n  if m == nil then HOME_GUID = nil return end\n  local militant = ((self.is_face_down == true) == MILITANT_FACE_DOWN)\n  local w = spotOn(m, militant)\n  if w == nil then return end\n  pcall(function() HOME_GUID = m.getGUID() end)\n  -- x/z only: the height is left exactly as it is, so the token settles onto whatever is under it at\n  -- THIS spot rather than onto the height of the one it came from.\n  LIFT_FROM = nil\n  self.setPosition({ w.x, p.y, w.z })\n  -- TURN IT, DO NOT UN-FLIP IT. This set { 0, y, 0 }, and Z is the flip axis: every placement\n  -- levelled the token face-up, so flipping it to militant sent it to the centre and immediately\n  -- turned it back to peaceful. Maintainer, 2026-09-07: \"the center snap still flips it to peaceful\",\n  -- and then \"when I flip it to militant it goes to the side snap and flips back to peaceful\". Only Y\n  -- is ours; X and Z belong to whoever flipped it.\n  local okr, r = pcall(function() return m.getRotation() end)\n  local okc, c = pcall(function() return self.getRotation() end)\n  if okr and r ~= nil and okc and c ~= nil then\n    self.setRotation({ c.x, r.y + FROG_FACING + (militant and 0 or SIDE_TILT), c.z })\n  end\nend\n\nfunction onDrop(player_color) rttPlaceOnMarker() end\n\n-- A FLIP MOVES THE TOKEN. This is the half that was missing: flipping in place never calls onDrop, so\n-- a token turned peaceful stayed sitting on the symbol it was supposed to uncover. Maintainer,\n-- 2026-09-07: \"most importantly flipping the enclave when it is on one of the two snaps needs to\n-- change its position.\"\n--\n-- onRotate fires for a SPIN as well, and re-placing on one of those would undo a player turning the\n-- token by hand -- so only a change of FLIP counts.\n--\n-- IT MOVES WHEN THE TOKEN LANDS, NOT WHILE IT TURNS. Maintainer, 2026-09-07: \"the move from both\n-- snaps happens only when it lands on the marker not during the flip.\" onRotate fires as the\n-- animation STARTS -- the token is still turning, is_face_down still reads the old face, and moving it\n-- then drags a spinning piece sideways. So this waits for the object to report itself at rest and\n-- unheld, and only then reads which side is up and places it. FLIP_SETTLE is a floor, not the answer:\n-- the check keeps looking until the token is actually down, and gives up rather than hang if it never\n-- settles (knocked off the table, picked straight back up).\nlocal function whenSettled(fn, tries)\n  local ready = false\n  pcall(function()\n    ready = (self.held_by_color == nil) and (self.resting ~= false)\n      and (self.isSmoothMoving ~= nil and self.isSmoothMoving() ~= true)\n  end)\n  if ready then fn() return end\n  if tries <= 0 then return end\n  Wait.time(function() whenSettled(fn, tries - 1) end, FLIP_SETTLE)\nend\n\nfunction onRotate(spin, flip, player_color, old_spin, old_flip)\n  if flip == old_flip then return end\n  -- across NOW, so the move reads as part of the flip...\n  pcall(rttGlideToSpot)\n  -- ...and the placement re-applied once it lands, as the backstop: if the token was knocked or the\n  -- glide interrupted, this is what puts it exactly on the spot.\n  Wait.time(function() whenSettled(function() pcall(rttPlaceOnMarker) end, SETTLE_TRIES) end,\n            FLIP_SETTLE)\nend", "LuaScriptState": "", "XmlUI": ""}]]},{move_to={ -4.849718, 0.099997, 5.29008 }, json=[[{"GUID": "2c86a8","Name": "Custom_Model","Transform": {"posX": -6.836046,"posY": 35.8542328,"posZ": -45.8038139,"rotX": 0.016477447,"rotY": 179.958359,"rotZ": 0.08025028,"scaleX": 2.34,"scaleY": 2.34,"scaleZ": 2.93},"Nickname": "Diaspora Warrior","Description": "","GMNotes": "","AltLookAngle": {"x": 0.0,"y": 0.0,"z": 0.0},"ColorDiffuse": {"r": 0.6901961,"g": 0.5960784,"b": 0.0156862736},"LayoutGroupSortIndex": 0,"Value": 0,"Locked": false,"Grid": true,"Snap": false,"IgnoreFoW": false,"MeasureMovement": false,"DragSelectable": true,"Autoraise": true,"Sticky": true,"Tooltip": true,"GridProjection": false,"HideWhenFaceDown": false,"Hands": false,"CustomMesh": {"MeshURL": "https://steamusercontent-a.akamaihd.net/ugc/2508034524414882588/A874A4AF718BCE6A7E0915815C3D0A3565FECCAC/","DiffuseURL": "https://steamus