EVERYTHING['Tools']['Mini-Mood Manager'] = {color='', data={
  {move_to={ 10.727003, 0.099988, 11.422435 }, json=[[{"GUID": "c109a8","Name": "Custom_Tile","Transform": {"posX": 55.7401352,"posY": 35.76874,"posZ": -39.6699371,"rotX": 0.0168962833,"rotY": 180.02034,"rotZ": 0.07970369,"scaleX": 3.97335124,"scaleY": 1.0,"scaleZ": 3.97335124},"Nickname": "","Description": "","GMNotes": "","ColorDiffuse": {"r": 1.0,"g": 0.364111274,"b": 0.364111274},"LayoutGroupSortIndex": 0,"Value": 0,"Locked": false,"Grid": true,"Snap": true,"IgnoreFoW": false,"MeasureMovement": false,"DragSelectable": true,"Autoraise": true,"Sticky": true,"Tooltip": true,"GridProjection": false,"HideWhenFaceDown": false,"Hands": false,"CustomImage": {"ImageURL": "https://steamusercontent-a.akamaihd.net/ugc/1627479847502716261/4A4AE226818F31E8BC38093C94EBA11BD9BAB415/","ImageSecondaryURL": "https://steamusercontent-a.akamaihd.net/ugc/1627479847502717190/118BE606223EEAFAEB063D51868A3107DEA7FCB0/","ImageScalar": 1.0,"WidthScale": 0.0,"CustomTile": {"Type": 3,"Thickness": 0.145000011,"Stackable": false,"Stretch": true}},"LuaScript": "local CARD_SCALE_XZ = 2.36\r\n\r\nlocal _scriptingZone = false\r\n\r\nlocal pickedUp = false\r\n\r\nfunction onLoad(save_state)\r\n      createScriptingZone()\r\n      Wait.time(resetScriptingZone,0.3)\r\nend\r\n\r\nfunction onPickUp(player_color)\r\n  _scriptingZone = nil\r\n  pickedUp = true\r\nend\r\n\r\nfunction onDrop(playerColor)\r\n    if _scriptingZone == nil then createScriptingZone() end\r\n    Wait.time(resetScriptingZone, 0.3)\r\n    pickedUp = false\r\nend\r\n\r\nfunction onRotate()\r\n    if _scriptingZone == nil and pickedUp == false then createScriptingZone() end\r\n    Wait.time(resetScriptingZone, 0.3)\r\nend\r\n\r\n-------------------------------------------------------------------------------\r\n\r\nfunction isRelevantCard(enterObject)\r\n    assert(type(enterObject) == 'userdata')\r\n    return enterObject.tag == 'Card' and enterObject.hasTag(\"Rat Mood\")\r\nend\r\n\r\nfunction onObjectEnterScriptingZone(zone, enterObject)\r\n    if not enterObject then\r\n        return\r\n    end\r\n    if zone == _scriptingZone and isRelevantCard(enterObject) then\r\n        enterObject.setScale({\r\n            x = CARD_SCALE_XZ,\r\n            y = 1,\r\n            z = CARD_SCALE_XZ,\r\n        })\r\n    end\r\n\r\n    local size = enterObject.getBoundsNormalized().size\r\nend\r\n\r\nfunction onObjectLeaveScriptingZone(zone, leaveObject)\r\n    if not leaveObject then\r\n        return\r\n    end\r\n    if zone == _scriptingZone and isRelevantCard(leaveObject) then\r\n        leaveObject.setScale({\r\n            x = 0.57,\r\n            y = 1,\r\n            z = 0.57,\r\n        })\r\n    end\r\nend\r\n\r\n-------------------------------------------------------------------------------\r\n\r\nfunction createScriptingZone()\r\n    assert(not _scriptingZone)\r\n\r\n    local zoneName = self.getGUID() .. ' SCRIPTING ZONE'\r\n\r\n    local function getScriptingZone()\r\n        for _, object in ipairs(getAllObjects()) do\r\n            if object.tag == 'Scripting' and object.getName() == zoneName then\r\n                return object\r\n            end\r\n        end\r\n    end\r\n\r\n    _scriptingZone = getScriptingZone() or spawnObject({\r\n        type              = 'ScriptingTrigger',\r\n        position          = self.getPosition(),\r\n        rotation          = self.getRotation(),\r\n        sound             = false,\r\n        snap_to_grid      = false\r\n    })\r\n    _scriptingZone.setName(zoneName)\r\nend\r\n\r\n-- Attaching via joint prevents mat from being movable (???).\r\n-- Just reposition zone when mat moves.\r\nfunction resetScriptingZone()\r\n\r\n    local angleY = self.getRotation().y\r\n    local posX = self.getPosition().x\r\n    local posZ = self.getPosition().z\r\n\r\n    local angle = -1.18 - (math.pi/180 * angleY) + math.pi\r\n\r\n    local offsetX = math.cos(angle) * 0.0\r\n    local offsetZ = math.sin(angle) * 0.0\r\n\r\n    local posy = Vector({posX + offsetX,self.getPosition().y,posZ + offsetZ})\r\n    local roty = self.getRotation()\r\n\r\n    if _scriptingZone != nil then\r\n      _scriptingZone.setPosition({x = posy.x, y = posy.y, z = posy.z})\r\n      _scriptingZone.setRotation({x = roty.x, y = roty.y, z = roty.z})\r\n\r\n      local size = self.getBoundsNormalized().size\r\n      _scriptingZone.setScale({\r\n          x = 1,\r\n          y = 12,  -- 4 is enough, could make larger to be safe\r\n          z = 4,\r\n      })\r\n    end\r\nend\r\n","LuaScriptState": "","XmlUI": "","AttachedSnapPoints": [{"Position": {"x": 0.8682495,"y": 0.145000756,"z": -0.6981082},"Rotation": {"x": 1.69722547E-08,"y": -0.000123102684,"z": 2.082393E-07}},{"Position": {"x": 0.8655648,"y": 0.1450008,"z": -0.2337082},"Rotation": {"x": 8.128323E-08,"y": -0.000123102684,"z": -4.212465E-09}},{"Position": {"x": 0.8662462,"y": 0.14500083,"z": 0.230688423},"Rotation": {"x": 4.51235138E-08,"y": -0.0005192536,"z": -1.78288175E-08}},{"Position": {"x": 0.866971254,"y": 0.145000875,"z": 0.6951484},"Rotation": {"x": -5.01061841E-08,"y": -0.00408461224,"z": 1.31203066E-07}},{"Position": {"x": -0.000225627009,"y": 0.145000458,"z": 0.001822692},"Rotation": {"x": 3.04065964E-08,"y": -0.000287027215,"z": -3.73396952E-10}},{"Position": {"x": -0.856729567,"y": 0.145000115,"z": 0.229847819},"Rotation": {"x": -3.69597046E-08,"y": -0.000123102684,"z": -1.95803711E-08}},{"Position": {"x": -0.856361151,"y": 0.145000085,"z": -0.238116443},"Rotation": {"x": -2.98189065E-08,"y": -0.000123102684,"z": 2.522463E-08}},{"Position": {"x": -0.8581742,"y": 0.145000041,"z": -0.695575833},"Rotation": {"x": 1.38458688E-07,"y": -0.000136763061,"z": 4.893539E-08}},{"Position": {"x": -0.86614877,"y": 0.14500016,"z": 0.6908933},"Rotation": {"x": -1.85088E-07,"y": -0.000123102684,"z": 2.3357785E-08}}]
