= '0',\r\n position = {0.45, 0.25, 0.4},\r\n scale = {0.9, 0.5, 0.9},\r\n width = 0,\r\n height = 0,\r\n font_size = 120\r\n })\r\n self.createButton({\r\n click_function = \"nothing\",\r\n function_owner = self,\r\n label = '0',\r\n position = {0.45, 0.25, 0.73},\r\n scale = {0.9, 0.5, 0.9},\r\n width = 0,\r\n height = 0,\r\n font_size = 120\r\n })\r\nend\r\n\r\nfunction updateButtons()\r\n mice = 0\r\n foxes = 0\r\n bunnies = 0\r\n items = Physics.cast({\r\n origin = self.positionToWorld({-0.0, 0.2, 0.45}),\r\n direction = self.getTransformUp(),\r\n type = 3,\r\n size = {3, 0.1, 6},\r\n max_distance = 2,\r\n })\r\n for _, item in ipairs(items) do\r\n if item.hit_object.tag == \"Card\" then\r\n addCard(item.hit_object.getDescription())\r\n end\r\n if item.hit_object.tag == \"Deck\" then\r\n for _, card in ipairs(item.hit_object.getObjects()) do\r\n addCard(card.description)\r\n end\r\n end\r\n end\r\n\r\n self.editButton({index=0,label=tostring(mice)})\r\n self.editButton({index=1,label=tostring(bunnies)})\r\n self.editButton({index=2,label=tostring(foxes)})\r\nend\r\n\r\n----#include root\\lizardboard","LuaScriptState": "","XmlUI": "","AttachedSnapPoints": [{"Position": {"x": -0.7220492,"y": 0.200000763,"z": 0.0283633228},"Rotation": {"x": 4.63632581E-08,"y": -0.00319994357,"z": 6.541245E-08},"Tags": []},{"Position": {"x": -0.732150555,"y": 0.200000763,"z": 0.374904454},"Rotation": {"x": 4.63632581E-08,"y": -0.00319994357,"z": 6.541245E-08},"Tags": []},{"Position": {"x": -0.7363231,"y": 0.200000763,"z": 0.7319697},"Rotation": {"x": 4.63632581E-08,"y": -0.00319994357,"z": 6.541245E-08},"Tags": []},{"Position": {"x": 0.483385444,"y": 0.200000763,"z": -0.010193795},"Rotation": {"x": 4.63632581E-08,"y": -0.00319994357,"z": 6.541245E-08},"Tags": []}]
