on    = self.getTransformUp(),\r\n\t\torientation  = Vector(self.getRotation()) + Vector({0, 87, 0}), --{0, 87, 0},\r\n        type         = 3,\r\n        size         = {11.5, 7, 7},\r\n        max_distance = 2\r\n    })\r\n    for _, item in ipairs(items) do\r\n        if item.hit_object.tag == \"Figurine\" then\r\n            addWarrior(item.hit_object.getName())\r\n        end\r\n    end\r\n\r\n    self.editButton({index=0,label=tostring(math.floor(warriors/5))})\r\nend\r\n----#include root\\coffinkeeper","LuaScriptState": "","XmlUI": "","States": {"1": {"GUID": "b5014a","Name": "Custom_Assetbundle","Transform": {"posX": 58.9902344,"posY": 35.65214,"posZ": -80.68422,"rotX": 0.01684398,"rotY": 180.0203,"rotZ": 0.07991003,"scaleX": 5.70000267,"scaleY": 5.70000267,"scaleZ": 5.70000267},"Nickname": "Koffin Keeper","Description": "Holds & counts meeples for Root's 'Coffin Makers' card.\n\nMouseover & press '2' to activate!\n\n*MEEPLES MUST HAVE NAMES THAT INCLUDE THE WORD 'WARRIOR' OR THEY WILL NOT BE COUNTED!*\n\nMade by Nevakanezah","GMNotes": "","ColorDiffuse": {"r": 1.0,"g": 1.0,"b": 1.0},"LayoutGroupSortIndex": 0,"Value": 0,"Locked": false,"Grid": true,"Snap": true,"IgnoreFoW": false,"MeasureMovement": false,"DragSelectable": true,"Autoraise": true,"Sticky": true,"Tooltip": true,"GridProjection": false,"HideWhenFaceDown": false,"Hands": false,"CustomAssetbundle": {"AssetbundleURL": "https://steamusercontent-a.akamaihd.net/ugc/1736675300477798481/E3D9619EF83A2523492157D05EE53F7B53FF1946/","AssetbundleSecondaryURL": "","MaterialIndex": 1,"TypeIndex": 1,"LoopingEffectIndex": 0},"LuaScript": "","LuaScriptState": "","XmlUI": ""}}
