\r\n    msg = \"The mob spreads to FOX!\"\r\n  elseif suit == 3 then\r\n    msg = \"The mob spreads to RABBIT!\"\r\n  end\r\n  broadcastToAll(msg, color)\r\nend\r\n","LuaScriptState": "","XmlUI": ""
