EVERYTHING['Tools']['Bat Bungler'] = {color='', data={
  {move_to={ 9.241642, 0.103335, 8.426046 }, json=[[{"GUID": "8e0f68","Name": "Custom_Assetbundle","Transform": {"posX": 7.26880455,"posY": 35.9280853,"posZ": 101.877525,"rotX": 0.0242541246,"rotY": 179.994934,"rotZ": 0.07988404,"scaleX": 3.09999824,"scaleY": 3.09999824,"scaleZ": 3.09999824},"Nickname": "","Description": "","GMNotes": "","AltLookAngle": {"x": 0.0,"y": 0.0,"z": 0.0},"ColorDiffuse": {"r": 1.0,"g": 0.7838254,"b": 0.240565121},"LayoutGroupSortIndex": 0,"Value": 0,"Locked": false,"Grid": true,"Snap": true,"IgnoreFoW": false,"MeasureMovement": false,"DragSelectable": true,"Autoraise": true,"Sticky": true,"Tooltip": true,"GridProjection": false,"HideWhenFaceDown": false,"Hands": false,"CustomAssetbundle": {"AssetbundleURL": "https://steamusercontent-a.akamaihd.net/ugc/15027362861715032038/97CB9376D54267BA985E65D67DC92B37C8ADA16C/","AssetbundleSecondaryURL": "","MaterialIndex": 2,"TypeIndex": 1,"LoopingEffectIndex": 0},"LuaScript": "params = {\r\n  click_function = \"click_roll\",\r\n  function_owner = self,\r\n\r\n  position       = {0, 1, 0.5},\r\n  rotation       = {-45, 0, 0},\r\n  width          = 1060,\r\n  height         = 1060,\r\n\r\n  color          = {1, 1, 1, 0},\r\n  tooltip        = \"Empower!\",\r\n}\r\nself.createButton(params)\r\n\r\nfunction click_roll(_, color)\r\n  if rollInProgress == nil or rollInProgress == false then\r\n    roll_empower(color)\r\n  end\r\nend\r\n\r\nfunction roll_empower(color)\r\n  rollInProgress = true\r\n  roll = math.random(0, 3)\r\n\r\n  Wait.frames(function() playRollResults(roll, color) end, 200)\r\n  Wait.frames(function() rollInProgress = false end, 300)\r\n\r\n  -- Launch sound effect and rolling animation, and let them play out\r\n  animationIndex = 4 + (roll * 2) -- Indices for normal rolls are 5,7,9,11, and i don't want to make a big case statement.\r\n  altAnimProbability = 20 -- Likelihood of alternate animations, from 0-100%.\r\n\r\n  if math.random(1, 100) <= altAnimProbability then\r\n    animationIndex = animationIndex + 1 -- Indices for silly alt animations are 6,8,10,12.\r\n  end\r\n  \r\n  self.AssetBundle.playLoopingEffect(roll) -- hold the current number that was rolled.\r\n  self.AssetBundle.playTriggerEffect(animationIndex)\r\n  self.AssetBundle.playTriggerEffect(0)\r\n  -- broadcastToAll(\"Roll_\" .. roll .. \" AnimIndex_\" .. animationIndex .. \" RollInProg_\" .. tostring(rollInProgress), color)\r\nend\r\n\r\nfunction playRollResults(roll, color)\r\n  msg = \"Empower for \" .. roll .. \"!\"\r\n\r\n  -- SFX\r\n  if roll == 0 then\r\n    self.AssetBundle.playTriggerEffect(3) -- Tadaaaa!\r\n  elseif roll == 1 or roll == 2 then\r\n    self.AssetBundle.playTriggerEffect(1) -- Generic \"Ding!\"\r\n  elseif roll == 3 then\r\n    self.AssetBundle.playTriggerEffect(2) -- Whomp whomp.\r\n  end\r\n\r\n  broadcastToAll(msg, color)\r\n\r\nend\r\n","LuaScriptState": "","XmlUI": ""
