s or 0\n  -- A SHEET FROM BEFORE THE FLAG. It restores with S.started nil, which would read as a game that\n  -- has not begun and put a running game back to ROUND 0. A locked cell is a played turn, which is\n  -- the same line rttHasData draws for the reset warning.\n  if S.started == nil then S.started = (rttHasData() == true) end\n  -- LIVE TURN STATE DOES NOT SURVIVE A RELOAD, because it describes a moment, not a game.\n  --   turnHolder is the colour holding the turn RIGHT NOW; it arms the duplicate-pass guard, so a\n  --   value from before the reload made the first pass after loading look stale and swallowed it.\n  --   turnStart is an absolute os.time. Kept across a save it measured the previous turn from\n  --   whenever the game was put away -- a turn \"lasting\" as long as the save sat on disk, printed\n  --   without a cap on minutes.\n  -- Both are re-established by the first real pass; the locks, the rounds and the names all persist\n  -- as before.\n  S.turnHolder = nil\n  S.turnStart = now()\n  -- A game saved before the round became explicit carries only S.turns and the locks. Recover the\n  -- round from the locks themselves -- the highest column anybody actually filled -- rather than from\n  -- the old division, which is the thing that was wrong. Each row's lastRound is seeded the same way,\n  -- so a resumed game keeps locking exactly where it left off.\n  if S.round == nil then\n    local maxr = 0\n    for _, row in ipairs(S.rows or {}) do\n      local last = 0\n      for r = 1, #(row.locks or {}) do\n        if row.locks[r] ~= nil and row.locks[r] ~= -1 then last = r end\n      end\n      row.lastRound = (last > 0) and last or nil\n      if last > maxr then maxr = last end\n    end\n    -- ...AND WHETHER THAT ROUND IS FINISHED. The round is eager now: it advances the moment the table\n    -- comes round, not when the next row locks. So a save whose every row has locked column `maxr` is\n    -- a save sitting at the START of maxr + 1, and resuming into maxr would write over a finished\n    -- column. Under the old lazy scheme both readings collapsed to the same number.\n    local complete = (maxr > 0)\n    for _, row in ipairs(S.rows or {}) do\n      local v = (row.locks or {})[maxr]\n      if v == nil or v == -1 then complete = false end\n    end\n    S.round = math.max(1, maxr + (complete and 1 or 0))\n  end\n  S.active = S.active or 1\n  if S.active > math.max(1, #S.rows) then S.active = 1 end\n  local domWinner = nil\n  for _, row in ipairs(S.rows) do\n    row.locks = row.locks or {}\n    row.edits = row.edits or {}\n    row.crafts = row.crafts or nil\n    row.score = row.score or -1\n    row.player = row.player or \"\"\n    if row.dom ~= nil then\n      row.dom.turn = math.max(1, math.floor(tonumber(row.dom.turn) or 1))\n      row.dom.round = math.max(1, math.floor(tonumber(row.dom.round) or 1))\n      row.dom.suit = tostring(row.dom.suit or \"\"):lower()\n      row.dom.score = tonumber(row.dom.score) or row.score\n      row.dom.won = row.dom.won == true\n      local brazen = row.dom.kind == \"brazen_demagogue\" or row.dom.frozen == false\n      row.dom.kind = brazen and \"brazen_demagogue\" or \"standard\"\n      row.dom.frozen = not brazen\n      if row.dom.markerGuid == \"\" then row.dom.markerGuid = nil end\n      if row.dom.won then domWinner = row.fac end\n    end\n  end\n  if domWinner ~= nil then\n    S.winner = domWinner\n    S.winnerReason = \"dominance\"\n    S.winnerLock = nil\n  elseif S.winner ~= nil and S.winnerReason == nil then\n    S.winnerReason = \"score\"\n  end\n  S.cols = S.cols or 10\n  S.scaleMode = S.scaleMode or 1\n  if S.sizePct == nil then\n    local oldIdx = math.floor(tonumber(S.sizeIdx) or 2)\n    local oldMul = LEGACY_SIZE_MULS[oldIdx] or LEGACY_BASE_MUL\n    S.sizePct = math.floor(oldMul / LEGACY_BASE_MUL * 10 + 0.5) * 10\n  end\n  -- A brand-new RTT spawn has no LuaScriptState, so recover the percentage\n  -- remembered by the prior copy.  A real saved state always w